// inviteTokenIn returns the token in the link of the newest invite email sent to the address.
func inviteTokenIn(t *testing.T, e *apitest.Env, to string) string {
	t.Helper()
	msgs := e.Mail.Messages()
	for i := len(msgs) - 1; i >= 0; i-- {
		if msgs[i].To != to {
			continue
		}
		m := regexp.MustCompile(`token=([^\s]+)`).FindStringSubmatch(msgs[i].Body)
		if m == nil {
			t.Fatalf("no link in %q", msgs[i].Body)
		}
		token, _ := url.QueryUnescape(m[1])
		return token
	}
	t.Fatalf("no invite email to %s", to)
	return ""
}

func TestInviteTokens(t *testing.T) {
	e := apitest.New(t)
	// invite sends an invite as the owner and returns it with the token from its email. The API answer must not contain the token.
	invite := func(email string) (store.Invite, string) {
		t.Helper()
		r := e.Do("POST", "/v1/invites", e.Acme.Key, map[string]string{"email": email, "role": "member"})
		if r.Code != http.StatusCreated {
			t.Fatalf("invite %s: %s", email, r)
		}
		token := inviteTokenIn(t, e, email)
		if strings.Contains(string(r.Body), token) || strings.Contains(string(r.Body), "token_hash") {
			t.Fatalf("the invite answer exposes its token: %s", r.Body)
		}
		var inv store.Invite
		r.JSON(t, &inv)
		return inv, token
	}
	// accept accepts a token as the invited person and returns the response.
	accept := func(token string) *apitest.Response {
		return e.Do("POST", "/v1/invites/accept", "", map[string]string{"token": token, "name": "New Person"})
	}
	// wantError checks an error response's status and code.
	wantError := func(r *apitest.Response, status int, code string) {
		t.Helper()
		if r.Code != status || r.Map(t)["error"] != code {
			t.Fatalf("want %d %s: %s", status, code, r)
		}
	}

	_, token := invite("new@people.example")
	if !regexp.MustCompile(`^[A-Za-z0-9_-]{43}$`).MatchString(token) {
		t.Fatalf("token %q is not 43 unpadded base64url characters", token)
	}
	sum := sha256.Sum256([]byte(token))
	snapshot, err := json.Marshal(e.Store.Export())
	if err != nil {
		t.Fatal(err)
	}
	if strings.Contains(string(snapshot), token) || !strings.Contains(string(snapshot), hex.EncodeToString(sum[:])) {
		t.Fatal("the snapshot must hold the token's SHA-256 hash, not the token")
	}
	if r := e.Do("GET", "/v1/invites", e.Acme.Key, nil); strings.Contains(string(r.Body), token) {
		t.Fatalf("the invite list exposes the token: %s", r.Body)
	}

	// A new member accepts once. A second accept is refused.
	if r := accept(token); r.Code != http.StatusCreated {
		t.Fatalf("accept: %s", r)
	}
	wantError(accept(token), http.StatusGone, "invite_used")

	// A revoked invite is not found.
	revoked, revokedToken := invite("revoked@people.example")
	e.MustDo(http.StatusNoContent, "DELETE", "/v1/invites/"+revoked.ID, e.Acme.Key, nil, nil)
	wantError(accept(revokedToken), http.StatusNotFound, "invite_not_found")

	// Inviting an address again (ignoring case) revokes the old invite: only the newest token works.
	_, oldToken := invite("Case@People.example")
	_, newToken := invite("case@people.example")
	wantError(accept(oldToken), http.StatusNotFound, "invite_not_found")
	if r := accept(newToken); r.Code != http.StatusCreated {
		t.Fatalf("accept the newest invite: %s", r)
	}

	// An invite stays acceptable for 7 days from its creation, and no longer.
	_, lateToken := invite("late@people.example")
	e.Clock.Advance(7 * 24 * time.Hour)
	var pending struct {
		Items []struct {
			Email     string    `json:"email"`
			CreatedAt time.Time `json:"created_at"`
			ExpiresAt time.Time `json:"expires_at"`
		}
	}
	e.MustDo(http.StatusOK, "GET", "/v1/invites", e.Acme.Key, nil, &pending)
	if len(pending.Items) != 1 || pending.Items[0].Email != "late@people.example" {
		t.Fatalf("pending invites at 7 days = %+v", pending.Items)
	}
	if got := pending.Items[0].ExpiresAt.Sub(pending.Items[0].CreatedAt); got != 7*24*time.Hour {
		t.Fatalf("expires_at is %s after created_at", got)
	}
	e.Clock.Advance(time.Second)
	e.MustDo(http.StatusOK, "GET", "/v1/invites", e.Acme.Key, nil, &pending)
	if len(pending.Items) != 0 {
		t.Fatalf("an expired invite is listed: %+v", pending.Items)
	}
	wantError(accept(lateToken), http.StatusGone, "invite_expired")
}

