	_, lateToken := invite("late@people.example")
	e.Clock.Advance(7 * 24 * time.Hour)
	var pending struct {
		Items []struct {
			Email     string    `json:"email"`
			CreatedAt time.Time `json:"created_at"`
			ExpiresAt time.Time `json:"expires_at"`
		}
	}
	e.MustDo(http.StatusOK, "GET", "/v1/invites", e.Acme.Key, nil, &pending)
	if len(pending.Items) != 1 || pending.Items[0].Email != "late@people.example" {
		t.Fatalf("pending invites at 7 days = %+v", pending.Items)
	}
	if got := pending.Items[0].ExpiresAt.Sub(pending.Items[0].CreatedAt); got != 7*24*time.Hour {
		t.Fatalf("expires_at is %s after created_at", got)
	}
	e.Clock.Advance(time.Second)
	e.MustDo(http.StatusOK, "GET", "/v1/invites", e.Acme.Key, nil, &pending)
	if len(pending.Items) != 0 {
		t.Fatalf("an expired invite is listed: %+v", pending.Items)
	}
	wantError(accept(lateToken), http.StatusGone, "invite_expired")
}

